contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that performs the test
    function run(uint _unlockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // read balance-before for this test contract (msg.sender for C will be this contract)
        (uint before_balance,) = _getHolder(c, address(this));
        uint contractBefore = address(c).balance;

        // perform Put, capture whether it reverted
        bool reverted;
        try c.Put{value: amount}(_unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        (uint after_balance,) = _getHolder(c, address(this));
        uint contractAfter = address(c).balance;

        // If the call did not revert, then the holder balance must increase by exactly amount
        // and the contract's Ether balance must increase by exactly amount.
        assert(reverted || (after_balance == before_balance + amount && contractAfter == contractBefore + amount));
    }

    // helper to call the public getter Acc(address) which returns (unlockTime, balance)
    // Note: Acc is a public mapping of Holder structs, so compiler generates a getter with signature
    // function Acc(address) external view returns (uint unlockTime, uint balance);
    function _getHolder(C _c, address who) internal view returns (uint balance, uint unlockTime) {
        // call the autogenerated getter; it returns (uint unlockTime, uint balance)
        (uint _unlockTime, uint _balance) = _c.Acc(who);
        return (_balance, _unlockTime);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that performs the test
    // parameters:
    //  - initialDeposit: amount of wei to put into c for this test contract
    //  - unlockTime: value passed to Put
    //  - collectAmount: amount passed to Collect
    function run(uint initialDeposit, uint unlockTime, uint collectAmount) public payable {
        // supply initialDeposit from this contract's balance when calling Put
        require(address(this).balance >= initialDeposit);

        // read holder state and contract balance before any actions
        (uint before_unlock, uint before_balance) = c.Acc(address(this));
        uint contractBefore = address(c).balance;

        // perform Put to deposit initialDeposit (may revert)
        bool putReverted;
        try c.Put{value: initialDeposit}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // read after Put
        (uint mid_unlock, uint mid_balance) = c.Acc(address(this));
        uint contractMid = address(c).balance;

        // Attempt Collect of collectAmount (may revert)
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read after Collect
        (uint after_unlock, uint after_balance) = c.Acc(address(this));
        uint contractAfter = address(c).balance;

        // RULE:
        // If Collect succeeded (did not revert), then the holder's recorded balance decreased by exactly collectAmount
        // and the contract's Ether balance decreased by exactly collectAmount.
        // If Collect reverted, we make no further requirement here.
        // The assertion must be reachable: ensure at least that Put could have succeeded or not; we assert a relation that depends on collectReverted.

        assert(collectReverted || (after_balance + collectAmount == mid_balance && contractAfter + collectAmount == contractMid));
    }

    // enable receiving Ether for the test contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test parameters:
    // depositAmount: amount to send in Put to ensure a balance >= MinSum and >= collectAmount
    // unlockTime: value passed to Put
    // collectAmount: amount to request via Collect
    function run(uint depositAmount, uint unlockTime, uint collectAmount) public payable {
        // require this contract holds enough Ether to fund the Put call
        require(address(this).balance >= depositAmount);

        // read holder state and contract balance before any actions
        (uint before_unlock, uint before_balance) = c.Acc(address(this));
        uint contractBefore = address(c).balance;

        // perform Put to deposit depositAmount (may revert)
        bool putReverted;
        try c.Put{value: depositAmount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // read after Put
        (uint mid_unlock, uint mid_balance) = c.Acc(address(this));
        uint contractMid = address(c).balance;

        // Attempt Collect of collectAmount (may revert)
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read after Collect
        (uint after_unlock, uint after_balance) = c.Acc(address(this));
        uint contractAfter = address(c).balance;

        // GENERAL RULE (single assert):
        // If Collect succeeded then all of the following hold:
        // 1) before calling Collect the holder's recorded balance (mid_balance) was >= c.MinSum() and >= collectAmount
        // 2) the holder's recorded balance decreased by exactly collectAmount (after_balance + collectAmount == mid_balance)
        // 3) the contract's Ether balance decreased by exactly collectAmount (contractAfter + collectAmount == contractMid)
        // If Collect reverted, no requirement is made.
        uint minSum = c.MinSum();
        assert(collectReverted || (mid_balance >= minSum && mid_balance >= collectAmount && after_balance + collectAmount == mid_balance && contractAfter + collectAmount == contractMid));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // depositAmount: Ether to send in Put to increase this contract's recorded balance
    // unlockTime: value passed to Put
    // collectAmount: amount to request via Collect
    function run(uint depositAmount, uint unlockTime, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);

        // read before-state
        (uint before_unlock, uint before_balance) = c.Acc(address(this));
        uint contractBefore = address(c).balance;
        uint minSum = c.MinSum();

        // perform Put to deposit depositAmount (may revert)
        bool putReverted;
        try c.Put{value: depositAmount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // read mid-state (state immediately before attempting Collect as observed after Put)
        (uint mid_unlock, uint mid_balance) = c.Acc(address(this));
        uint contractMid = address(c).balance;

        // attempt Collect
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read after-state
        (uint after_unlock, uint after_balance) = c.Acc(address(this));
        uint contractAfter = address(c).balance;

        // GENERAL RULE asserted for all inputs:
        // If Collect succeeded then:
        //  - mid_balance >= minSum
        //  - mid_balance >= collectAmount
        //  - block.timestamp > mid_unlock (unlock condition must hold at the time Collect executes)
        //  - after_balance == mid_balance - collectAmount
        //  - contractAfter == contractMid - collectAmount
        // If Collect reverted, no requirements.
        assert(collectReverted || (
            mid_balance >= minSum
            && mid_balance >= collectAmount
            && block.timestamp > mid_unlock
            && after_balance + collectAmount == mid_balance
            && contractAfter + collectAmount == contractMid
        ));
    }

    receive() external payable {}
}

contract InvMutTest {
