        (uint before_unlock, uint before_balance) = c.Acc(address(this));
        uint contractBefore = address(c).balance;

        // perform Put (may revert)
        bool putReverted;
        try c.Put{value: depositAmount}(unlockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // read mid-state (after Put attempt)
        (uint mid_unlock, uint mid_balance) = c.Acc(address(this));
        uint contractMid = address(c).balance;

        // attempt Collect
        bool collectReverted;
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read after-state
        (uint after_unlock, uint after_balance) = c.Acc(address(this));
        uint contractAfter = address(c).balance;

        // General rule:
        // If Collect succeeded then the recorded holder balance decreased exactly by collectAmount,
        // and the contract's balance decreased by at least collectAmount (the contract might have transferred less on failed send but only succeeds branch reaches balance update).
        // We allow Put to have reverted; rule only concerns Collect's effect when it returns successfully.
        assert(collectReverted || (after_balance + collectAmount == mid_balance && contractAfter + collectAmount <= contractMid));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call Put to deposit some Ether and then call Collect for some amount.
    // Params:
    //  - deposit: amount of wei to send to Put (must be >= MinSum to enable Collect success path)
    //  - collectAmt: requested amount to Collect
    //  - unlockOffset: seconds to add to current block.timestamp to set unlockTime (0 means use block.timestamp)
    function run(uint deposit, uint collectAmt, uint unlockOffset) public payable {
        require(address(this).balance >= deposit, "insufficient test balance");
        // 1) set up: call Put with unlock time = block.timestamp + unlockOffset (if 0 Put sets to block.timestamp)
        uint unlockTime = block.timestamp + unlockOffset;
        // call Put sending `deposit` wei
        c.Put{value: deposit}(unlockTime);

        // Read before-values: holder balance and contract balance
        (, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Attempt Collect and capture whether it reverted
        bool reverted;
        // Collect is payable in the contract but we don't need to send Ether when collecting
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        (, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule asserted:
        // - If Collect succeeded (not reverted) then:
        //     * afterBalance == beforeBalance - collectAmt
        //     * afterContractBal + collectAmt <= beforeContractBal  (contract balance decreased by at least collectAmt)
        //   If Collect reverted then balances remain unchanged: afterBalance == beforeBalance and afterContractBal == beforeContractBal
        assert(
            (!reverted
                && beforeBalance >= collectAmt
                && afterBalance == beforeBalance - collectAmt
                && beforeContractBal >= afterContractBal
                && (beforeContractBal - afterContractBal) >= collectAmt
            )
            || (reverted
                && afterBalance == beforeBalance
                && afterContractBal == beforeContractBal
            )
        );
    }

    // Allow receiving Ether so tests can fund this contract externally
    receive() external payable {}
}

