contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    //  - deposit: wei to send to Put (must be >= MinSum to allow Collect)
    //  - unlockTime: value passed to Put (set in the past or future)
    //  - am: amount to attempt to collect
    function run(uint deposit, uint unlockTime, uint am) public payable {
        // need funds to deposit
        require(address(this).balance >= deposit);

        // Read holder state before Put
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Make a deposit so this contract is the holder
        c.Put{value: deposit}(unlockTime);

        // After deposit, read state before Collect
        (uint midUnlock, uint midBal) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Try Collect and catch revert
        bool reverted;
        try c.Collect{value: 0}(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read state after Collect (or after revert)
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule:
        // - If Collect succeeded (reverted==false) then holder balance decreased by exactly am
        //   and contract balance decreased by at least am.
        // - If Collect reverted then holder balance and contract balance did not decrease.
        assert(
            (
                !reverted
                ? (midBal >= am && afterBal + am == midBal && midContractBal >= am && afterContractBal + am <= midContractBal)
                : (afterBal == midBal && afterContractBal == midContractBal)
            )
        );
    }

    // Accept ETH when Collect sends funds to this test contract
    receive() external payable {}
}

