contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run will call Put with an amount and unlock time, and then check that
    // the public getter Acc(msg.sender) shows the balance increased by amount
    // and that address(c).balance increased accordingly. We use the fact that
    // the test contract is the deployer and caller of c so Acc[address(this)] is accessible via the public mapping getter.
    function run(uint unlockTime, uint amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // read before-values
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // perform the call sending Ether
        c.Put{value: amount}(unlockTime);

        // read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule:
        // - Put must not decrease the recorded balance for the caller
        // - The recorded balance increases exactly by the sent amount
        // - The contract's Ether balance increases exactly by the sent amount
        // - The stored unlockTime becomes >= block.timestamp (as per contract logic), and is at least the max of previous unlock and block.timestamp or the provided unlockTime if greater
        assert(afterBalance == beforeBalance + amount && afterContractBal == beforeContractBal + amount && afterUnlock >= block.timestamp && afterUnlock >= beforeUnlock);
    }

    // allow receiving Ether to fund calls
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We drive Put to fund the caller's account, then attempt Collect for some amount.
    // Parameters:
    //  fundAmount - Ether to send to c via Put to ensure balance >= MinSum possibly
    //  unlockTime - unlock time passed to Put
    //  collectAmount - amount to attempt to Collect
    function run(uint unlockTime, uint fundAmount, uint collectAmount) public payable {
        // ensure this test contract has enough Ether to fund Put
        require(address(this).balance >= fundAmount, "insufficient test balance");

        // Read recorded holder info before funding
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // Fund the account of this contract in C by calling Put
        c.Put{value: fundAmount}(unlockTime);

        // After funding, read values
        (uint midUnlock, uint midBalance) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Now attempt Collect and observe whether it reverts.
        bool reverted;
        // We cannot nest state-changing calls inside try per constraints, so use try/catch top-level call as required.
        // Note: c.Collect is non-payable but declared payable in source; we call with no value.
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read final values after Collect attempt
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General rule:
        // If Collect did not revert then:
        //   - afterBalance == midBalance - collectAmount
        //   - afterContractBal == midContractBal - collectAmount
        // If Collect reverted then balances/state must be unchanged by the failed call:
        //   - afterBalance == midBalance
        //   - afterContractBal == midContractBal
        // Also, in any case, unlockTime recorded for this holder does not increase as a result of Collect (Collect never increases unlockTime):
        //   - afterUnlock <= midUnlock
        assert(
            // case: succeeded
            (!reverted && afterBalance + collectAmount == midBalance && afterContractBal + collectAmount == midContractBal && afterUnlock <= midUnlock)
            ||
            // case: reverted
            (reverted && afterBalance == midBalance && afterContractBal == midContractBal && afterUnlock == midUnlock)
        );
    }

    // allow receiving Ether to fund Put
    receive() external payable {}
}

