contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Parameters:
    //  unlockTime - passed to Put
    //  fundAmount - Ether to send when calling Put (must be > 0)
    function run(uint unlockTime, uint fundAmount) public payable {
        // we require a positive fund to avoid zero-value trivial behaviour
        require(fundAmount > 0, "fundAmount must be > 0");
        // ensure this contract has enough Ether to send
        require(address(this).balance >= fundAmount, "insufficient test balance");

        // record contract balance and holder balance before Put
        uint beforeContractBal = address(c).balance;
        (, uint beforeHolderBal) = c.Acc(address(this));

        // call Put sending fundAmount (must be top-level statement)
        c.Put{value: fundAmount}(unlockTime);

        // observe after-values
        uint afterContractBal = address(c).balance;
        (, uint afterHolderBal) = c.Acc(address(this));

        // General rule: for any positive fundAmount, Put increases both the contract's Ether
        // balance and the holder's recorded balance by exactly fundAmount, and thus
        // after - before == fundAmount for both measures.
        assert(afterContractBal == beforeContractBal + fundAmount && afterHolderBal == beforeHolderBal + fundAmount);
    }

    // allow receiving Ether to fund Put
    receive() external payable {}
}

contract InvMutTest {
