    constructor(C _c) { c = _c; }

    // run will try to call Put with a chosen unlock time and amount of ETH sent.
    // It asserts that if the call did not revert then Acc[this].balance increased by amount
    // and address(c).balance increased by amount as well.
    function run(uint unlockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // read before-values via public getters
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        bool reverted;
        // Call Put with value = amount. Capture whether it reverted.
        try c.Put{value: amount}(unlockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // If the call succeeded then the stored balance must have increased by amount
        // (no underflow/overflow assumptions because add_uint256 uses safe assert) and
        // the contract's ETH balance must increase by amount as well.
        assert(reverted || (afterBalance == beforeBalance + amount && afterContractBal == beforeContractBal + amount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call Put to deposit some funds and then attempt Collect of an amount.
    // Parameters:
    //  - depositAmount: amount of wei to send to Put to ensure the caller has funds
    //  - unlockOffset: seconds to add to block.timestamp when setting unlock (can be 0)
    //  - collectAmount: amount to attempt to Collect
    function run(uint depositAmount, uint unlockOffset, uint collectAmount) public payable {
        // ensure this test contract can send the requested deposit
        require(address(this).balance >= depositAmount);

        // Record contract balance before any interaction
        uint beforeContractBal = address(c).balance;
        // Record recorded balance for this test contract before deposit
        (uint beforeUnlock, uint beforeRecordedBal) = c.Acc(address(this));

        // Make a deposit by calling Put with value = depositAmount
        // We set unlock time to block.timestamp + unlockOffset so it may or may not be withdrawable.
        c.Put{value: depositAmount}(block.timestamp + unlockOffset);

        // After deposit, read recorded balance and contract balance
        (uint midUnlock, uint midRecordedBal) = c.Acc(address(this));
        uint midContractBal = address(c).balance;

        // Now attempt to Collect collectAmount and observe whether it reverts
        bool revertedCollect;
        try c.Collect{value: 0}(collectAmount) {
            revertedCollect = false;
        } catch {
            revertedCollect = true;
        }

        // Read after-values
        (uint afterUnlock, uint afterRecordedBal) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // General property:
        // If Collect succeeded (did not revert) then
        //  - the recorded balance for this test contract decreased by exactly collectAmount,
        //  - and the contract's on-chain balance decreased by at least collectAmount.
        // If Collect reverted then we make no further requirement.
        assert(revertedCollect || (midRecordedBal >= collectAmount && afterRecordedBal + collectAmount == midRecordedBal && midContractBal >= collectAmount && midContractBal - afterContractBal >= collectAmount));
    }

    // receive to accept ETH sent to this test contract (not strictly required but safe)
