contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(uint putUnlock, uint putAmount, uint collectAmount) public payable {
        // ensure we have Ether to send for Put
        require(address(this).balance >= putAmount, "insufficient balance for put");

        // read before-values: holder struct is accessible via public getter Acc(address)
        (uint beforeUnlock, uint beforeBalance) = c.Acc(address(this));
        uint beforeContractBal = address(c).balance;

        // perform Put sending putAmount wei
        c.Put{value: putAmount}(putUnlock);

        // read after Put values
        (uint afterUnlock, uint afterBalance) = c.Acc(address(this));
        uint afterContractBal = address(c).balance;

        // Now attempt Collect for collectAmount. We need to catch revert.
        bool collectReverted = false;
        // we must ensure we can send gas and not depend on msg.value; Collect is payable but doesn't use msg.value
        try c.Collect{value: 0}(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read final values
        (uint finalUnlock, uint finalBalance) = c.Acc(address(this));
        uint finalContractBal = address(c).balance;

        /* General rule asserted:
           1) The Put call increased the recorded balance by exactly putAmount and contract balance by same amount;
           2) Collect, if it succeeded, reduces the recorded balance by collectAmount and reduces contract balance by at least collectAmount (it may also have reduced by exactly collectAmount);
           3) Collect never increases the recorded balance; if it reverted, balances remain unchanged from after Put.
        */
        assert(
            // Put effect: recorded balance increase equals putAmount and contract balance increase equals putAmount
            (afterBalance == beforeBalance + putAmount && afterContractBal == beforeContractBal + putAmount && afterUnlock >= beforeUnlock) &&
            // Collect effect: either reverted and no change, or succeeded and balance decreased by collectAmount
            (
                (collectReverted && finalBalance == afterBalance && finalContractBal == afterContractBal) ||
                (!collectReverted && finalBalance + collectAmount == afterBalance && finalContractBal <= afterContractBal && finalContractBal + collectAmount <= afterContractBal + 1 wei)
            )
        );
    }

    // receive to accept refunds/transfers
    receive() external payable { }
}

