contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will deposit depositAmount (to potentially satisfy MinSum and available balance),
    // then attempt to Collect withdrawAmount. If Collect succeeds (does not revert),
    // the recorded stored balance for this contract must decrease by exactly withdrawAmount.
    function run(uint depositAmount, uint withdrawAmount) public payable {
        require(depositAmount >= 1 wei);
        require(address(this).balance >= depositAmount);

        // Ensure we start from known state: record stored balance before any interaction
        (uint beforeUnlock, uint beforeBal) = c.Acc(address(this));

        // Make a deposit to enable possible Collect. Use Put with unlockTime 0 so it sets to block.timestamp.
        c.Put{value: depositAmount}(0);

        // Record stored balance immediately before attempting Collect
        (uint midUnlock, uint midBal) = c.Acc(address(this));

        // Attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read stored balance after Collect attempt
        (uint afterUnlock, uint afterBal) = c.Acc(address(this));

        // If Collect succeeded, the stored balance must have decreased by exactly withdrawAmount.
        // Avoid arithmetic that can underflow in the test itself by expressing equality as:
        // midBal == afterBal + withdrawAmount  OR (if withdrawAmount is zero) midBal == afterBal
        // but we can write a single condition: either Collect reverted, or midBal >= afterBal and midBal - afterBal == withdrawAmount.
        // To avoid performing subtraction that could underflow in the assertion, check both cases safely.

        bool ok;
        if (reverted) {
            ok = true;
        } else {
            // Collect succeeded: require that midBal >= afterBal and the difference equals withdrawAmount
            // Check midBal >= afterBal first to ensure safe subtraction
            ok = (midBal >= afterBal) && (midBal - afterBal == withdrawAmount);
        }

        assert(ok);
    }

    receive() external payable {}
}
